const text = $input.first().json.message.text || '';
const chatId = $input.first().json.message.chat.id;
let cmd = 'new_idea', payload = text;

if (text.startsWith('/queue') || text.startsWith('/list')) { cmd = 'list_queue'; payload = ''; }
else if (text.startsWith('/draft ')) { cmd = 'trigger_draft'; payload = text.replace('/draft ', '').trim(); }
else if (text.startsWith('/schedule ')) { cmd = 'schedule'; payload = text.replace('/schedule ', '').trim(); }
else if (text.startsWith('/metrics ')) { cmd = 'metrics'; payload = text.replace('/metrics ', '').trim(); }
else if (text.startsWith('/help')) { cmd = 'help'; payload = ''; }
else if (text.startsWith('/ask ')) { cmd = 'agent'; payload = text.replace('/ask ', '').trim(); }
else if (text.startsWith('/drafts')) { cmd = 'show_drafts'; payload = text.replace('/drafts', '').trim(); }
else if (text.match(/^https?:\/\//)) { cmd = 'url_capture'; }


return [{ json: { cmd, payload, chatId, rawText: text, ts: new Date().toISOString() } }];

