const payload = $('Parse Command').first().json.payload;
const chatId = $('Parse Command').first().json.chatId;
const parts = payload.split(/\s+/);
if(parts.length<5) return [{json:{chatId,error:true,msg:'❌ Format: `/metrics ID PLATFORM views likes comments shares`\nExample: `/metrics CS-ABC twitter 450 12 3 5`'}}];
return [{json:{ chatId, error:false, id:'MT-'+Date.now().toString(36).toUpperCase(), content_id:parts[0], platform:parts[1], views:parseInt(parts[2])||0, likes:parseInt(parts[3])||0, comments:parseInt(parts[4])||0, shares:parseInt(parts[5])||0, logged_at:new Date().toISOString() }}];

const drafts = $input.all().map(i => i.json);
const chatId = $('Parse Command').first().json.chatId;

if (!drafts.length || !drafts[0].platform) {
  return [{ json: { chatId, msg: '❌ No drafts found for that ID. Run /draft first.' } }];
}

// Telegram caps a single message at 4096 chars; stay safely under it.
const LIMIT = 3800;

// One text block per draft.
const blocks = drafts.map(d => `📱 *${(d.platform || '').toUpperCase()}* (${d.char_count} chars)\n\n${d.draft_text || ''}`);

// Split any single block that is itself over the limit into hard chunks.
const pieces = [];
for (const block of blocks) {
  if (block.length <= LIMIT) {
    pieces.push(block);
  } else {
    for (let i = 0; i < block.length; i += LIMIT) {
      pieces.push(block.substring(i, i + LIMIT));
    }
  }
}

// Pack pieces into as few messages as possible, each under the limit.
const SEP = '\n\n---\n\n';
const messages = [];
let current = '📝 *Drafts:*';
for (const piece of pieces) {
  const candidate = current ? current + SEP + piece : piece;
  if (candidate.length > LIMIT) {
    if (current) messages.push(current);
    current = piece;
  } else {
    current = candidate;
  }
}
if (current) messages.push(current);

// One item per message -> Telegram node sends one message per item.
return messages.map(msg => ({ json: { chatId, msg } }));

const items = $input.all().map(i=>i.json);
const now = new Date();
const due = items.filter(i=>{
  if(i.published==='true'||i.published===true) return false;
  if(!i.scheduled_time) return false;
  return new Date(i.scheduled_time)<=now;
});
if(!due.length) return [{json:{noDue:true}}];
return due.map(i=>({json:i}));

const analytics = $('All Analytics').all().map(i=>i.json);
const content = $('All Content').all().map(i=>i.json);
const platStats={};
analytics.forEach(a=>{
  if(!platStats[a.platform]) platStats[a.platform]={posts:0,views:0,likes:0,comments:0,shares:0};
  const p=platStats[a.platform]; p.posts++; p.views+=parseInt(a.views)||0; p.likes+=parseInt(a.likes)||0; p.comments+=parseInt(a.comments)||0; p.shares+=parseInt(a.shares)||0;
});
const typeCount={}, stateCount={};
content.forEach(c=>{ typeCount[c.idea_type]=(typeCount[c.idea_type]||0)+1; stateCount[c.state]=(stateCount[c.state]||0)+1; });
return [{json:{summary:JSON.stringify({total:content.length,states:stateCount,types:typeCount,platforms:platStats,entries:analytics.length},null,2)}}];
